\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{shapes,arrows,positioning,backgrounds}
\pagestyle{empty}

% ── Custom Dark Theme: Deep Navy + Electric Blue / Teal / Gold ──
\definecolor{primary}{HTML}{3B82F6}      % Electric blue — title bar, key accents
\definecolor{secondary}{HTML}{14B8A6}    % Teal — second accent stripe
\definecolor{accent}{HTML}{F59E0B}       % Warm gold — highlights, stat accents
\definecolor{bgposter}{HTML}{0A1628}     % Deep navy page background
\definecolor{cardbg}{HTML}{112240}       % Card background (slightly lighter navy)
\definecolor{cardbg2}{HTML}{152850}      % Alt card background
\definecolor{cardtitlebg}{HTML}{1A3050}  % Card title area bg
\definecolor{textlight}{HTML}{E2E8F0}    % Body text
\definecolor{textgray}{HTML}{94A3B8}     % Captions, muted text
\definecolor{textmuted}{HTML}{64748B}    % Very muted
\definecolor{statbg}{HTML}{1A365D}       % Stat callout background
\definecolor{statgold}{HTML}{B8860B}     % Darker gold for stat accents
\definecolor{findingbg}{HTML}{0F1F3D}    % Key findings inner box bg
\definecolor{methodblue}{HTML}{1E3A6E}   % Method step box bg

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles for dark theme ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0.5pt, colframe=white!8, colback=cardbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary!80!white},
    coltitle=primary!80!white, colbacktitle=cardtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top,
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0.5pt, colframe=white!8, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary!80!white},
    coltitle=secondary!80!white, colbacktitle=cardtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top,
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0.5pt, colframe=white!8, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent!80!white},
    coltitle=accent!80!white, colbacktitle=cardtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top,
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0.5pt, colframe=primary!40, colback=primary!12!bgposter,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════
% TITLE BAR (span=3, top to row4)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{68}{82}\selectfont\bfseries Mapping Neural Circuit Architecture}\\[10pt]
  {\fontsize{48}{58}\selectfont\bfseries\color{white!85} Advances in Brain Connectivity Analysis}\\[16pt]
  {\fontsize{32}{40}\selectfont\color{white!70}%
    \textit{Nature} (2024) \quad | \quad DOI: 10.1038/s41586-024-07487-w \quad | \quad Nature Research Conference}
}

% ═══════════════════════════════════════════════════════
% STATS BANNER (span=3, row4 to row6) — 5 metric callouts
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg2, boxrule=0.5pt, colframe=white!10, arc=0pt,
  left=6pt, right=6pt, top=6pt, bottom=6pt,
  valign=center,
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{accent} \Large$\sim$\normalsize 125,000}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Neurons Mapped}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{accent} \Large$\sim$\normalsize 54M}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Synaptic Connections}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{accent} 37}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Circuit Motifs}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{accent} 94.2\%}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Classification Accuracy}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{38}{46}\selectfont\bfseries\color{secondary} Nature}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Published 2024}\vspace{8pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════
% ROW BAND A (row6 to row10) — Background | Methodology
% ═══════════════════════════════════════════════════════

% Col 1: Background & Motivation
\posterbox[bluecard, title={Background \& Motivation}
]{name=background, column=1, between=row6 and row10}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Classical neuroanatomy lacked resolution and scale to capture complete circuit-level wiring diagrams
    \item Understanding brain information processing requires detailed maps of neural connectivity
    \item Recent advances in EM, automated segmentation, and computational neuroscience converge to make large-scale connectomics feasible
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!20!bgposter}{\parbox{0.92\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{28}{36}\selectfont\color{primary!80!white}\textbf{Goal:} Bridge structural connectivity $\to$ functional organization}\vspace{6pt}%
  }}
}

% Col 2: Methodology Pipeline (visual flow)
\posterbox[tealcard, title={Methodology Pipeline}
]{name=methods, column=2, between=row6 and row10}{
  \fontsize{28}{36}\selectfont\centering
  \colorbox{methodblue}{\parbox{0.80\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\bfseries\color{primary!80!white} 1. Imaging}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textgray} Serial-section EM\\4$\times$4$\times$30 nm}\vspace{6pt}%
  }}\\[5pt]
  {\fontsize{36}{44}\selectfont\color{secondary}$\Downarrow$}\\[3pt]
  \colorbox{methodblue}{\parbox{0.80\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\bfseries\color{primary!80!white} 2. Segmentation}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textgray} Deep learning neuron tracing\\+ human proofreading}\vspace{6pt}%
  }}\\[5pt]
  {\fontsize{36}{44}\selectfont\color{secondary}$\Downarrow$}\\[3pt]
  \colorbox{methodblue}{\parbox{0.80\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\bfseries\color{primary!80!white} 3. Synapse Detection}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textgray} CNN classifier (94.2\% accuracy)}\vspace{6pt}%
  }}
}

% Col 3: Methods continued
\posterbox[tealcard, title={Analysis Framework}
]{name=methods2, column=3, between=row6 and row10}{
  \fontsize{28}{36}\selectfont\centering
  \colorbox{methodblue}{\parbox{0.80\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\bfseries\color{primary!80!white} 4. Circuit Analysis}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textgray} Graph-theoretic motif\\detection \& clustering}\vspace{6pt}%
  }}\\[5pt]
  {\fontsize{36}{44}\selectfont\color{secondary}$\Downarrow$}\\[3pt]
  \colorbox{methodblue}{\parbox{0.80\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\bfseries\color{primary!80!white} 5. Validation}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textgray} Calcium imaging \&\\optogenetic perturbation}\vspace{6pt}%
  }}\\[5pt]
  {\fontsize{36}{44}\selectfont\color{secondary}$\Downarrow$}\\[3pt]
  \colorbox{primary!25!bgposter}{\parbox{0.80\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{28}{34}\selectfont\bfseries\color{accent} Dataset Released}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textlight} Open-access resource}\vspace{6pt}%
  }}
}

% ═══════════════════════════════════════════════════════
% ROW BAND B (row10 to row17) — KEY FINDINGS (full width)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0.5pt, colframe=white!10, arc=0pt,
  left=14pt, right=14pt, top=8pt, bottom=8pt,
  valign=top,
  fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
  coltitle=accent, colbacktitle=cardtitlebg,
  toptitle=6pt, bottomtitle=6pt,
  titlerule=2.5pt, titlerule style={accent!60},
  borderline north={1pt}{0pt}{accent!40},
  borderline south={1pt}{0pt}{accent!40},
]{name=findings, column=1, span=3, between=row10 and row17, title={Key Findings}}{
  \fontsize{30}{38}\selectfont

  % Top row: Motifs + Hub Neurons
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{findingbg}{\parbox{0.94\linewidth}{%
      \vspace{8pt}\centering
      {\fontsize{52}{62}\selectfont\bfseries\color{accent} 37}\\[2pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{textlight} Distinct Connectivity Motifs}\\[4pt]
      {\fontsize{26}{34}\selectfont\color{textgray} Recurring building blocks of larger circuits,\\suggesting a modular wiring logic analogous\\to logic gates in digital circuits.}\vspace{8pt}%
    }}
    \vspace{8pt}

    \colorbox{findingbg}{\parbox{0.94\linewidth}{%
      \vspace{8pt}\centering
      {\fontsize{52}{62}\selectfont\bfseries\color{secondary} 4.7:1}\\[2pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{textlight} Layer-Specific Connectivity}\\[4pt]
      {\fontsize{26}{34}\selectfont\color{textgray} Recurrent-to-feedforward ratio in Layer 5.\\Feedforward dominates between L2/3 $\to$ L4,\\recurrent connections enriched within L5.}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{findingbg}{\parbox{0.94\linewidth}{%
      \vspace{8pt}\centering
      {\fontsize{52}{62}\selectfont\bfseries\color{accent} 3.5\% $\to$ 28\%}\\[2pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{textlight} Hub Neuron Dominance}\\[4pt]
      {\fontsize{26}{34}\selectfont\color{textgray} Hub neurons (\textasciitilde3.5\% of population)\\account for over 28\% of total synaptic\\output — highly non-uniform influence\\distribution across the network.}\vspace{8pt}%
    }}
    \vspace{8pt}

    \colorbox{findingbg}{\parbox{0.94\linewidth}{%
      \vspace{8pt}\centering
      {\fontsize{52}{62}\selectfont\bfseries\color{secondary} 6.2$\boldsymbol{\times}$}\\[2pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{textlight} Cell-Type-Specific Wiring}\\[4pt]
      {\fontsize{26}{34}\selectfont\color{textgray} Inhibitory interneurons show 6.2$\times$ higher\\connection specificity than excitatory neurons,\\challenging the assumption of broad\\inhibitory blanket coverage.}\vspace{8pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════
% ROW BAND C (row17 to bottom) — Implications | Future | Takeaways
% ═══════════════════════════════════════════════════════

% Col 1: Implications
\posterbox[bluecard, title={Implications}
]{name=implications, column=1, between=row17 and bottom}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Modular motifs suggest the brain uses a finite vocabulary of circuit elements for cortical computation
    \item Hub neurons as disproportionate network drivers explain how focal lesions or targeted stimulation produce widespread effects
    \item Direct relevance to neurological disease mechanisms and brain-computer interface design
  \end{itemize}
}

% Col 2: Future Directions
\posterbox[tealcard, title={Future Directions}
]{name=future, column=2, between=row17 and bottom}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Extend connectomic approach to additional brain regions and species
    \item Build a complete wiring diagram of the mammalian brain
    \item Integrate with functional recordings for structure-function mapping
    \item Refine automated reconstruction for higher throughput
  \end{itemize}
}

% Col 3: Key Takeaways
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row17 and bottom}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Largest connectomic dataset to date: \textbf{\textasciitilde125K neurons}, \textbf{\textasciitilde54M synapses}
    \item Discovery of \textbf{37 circuit motifs} reveals modular wiring principles
    \item \textbf{Open-access} dataset and tools released to accelerate community discovery
  \end{itemize}
  \vspace{6pt}
  \begin{center}
  \colorbox{primary!25!bgposter}{\parbox{0.90\linewidth}{%
    \centering\vspace{5pt}
    {\fontsize{24}{30}\selectfont\color{textgray}%
      \textit{Nature} (2024) \quad DOI: 10.1038/s41586-024-07487-w}\vspace{5pt}%
  }}
  \end{center}
}

\end{tcbposter}
\end{document}
LATEXEOF
