      {\fontsize{60}{70}\selectfont\bfseries\color{accent} 37}\\[3pt]
      {\fontsize{30}{38}\selectfont\bfseries\color{textlight} Distinct Connectivity Motifs}\\[5pt]
      {\fontsize{27}{35}\selectfont\color{textgray} Recurring building blocks reveal modular wiring logic —\\analogous to logic gates in digital circuits.}\vspace{10pt}%
    }}
    \vspace{10pt}

    \colorbox{findingbg}{\parbox{0.94\linewidth}{%
      \vspace{10pt}\centering
      {\fontsize{60}{70}\selectfont\bfseries\color{secondary} 4.7:1}\\[3pt]
      {\fontsize{30}{38}\selectfont\bfseries\color{textlight} Layer-Specific Connectivity Rules}\\[5pt]
      {\fontsize{27}{35}\selectfont\color{textgray} Recurrent-to-feedforward ratio in Layer 5. Feedforward\\dominates L2/3 $\to$ L4; recurrent enriched within L5.}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{findingbg}{\parbox{0.94\linewidth}{%
      \vspace{10pt}\centering
      {\fontsize{60}{70}\selectfont\bfseries\color{accent} 3.5\% $\to$ 28\%}\\[3pt]
      {\fontsize{30}{38}\selectfont\bfseries\color{textlight} Hub Neuron Dominance}\\[5pt]
      {\fontsize{27}{35}\selectfont\color{textgray} A small fraction (\textasciitilde3.5\%) of neurons accounts for\\28\% of total synaptic output — highly non-uniform\\influence distribution across the network.}\vspace{10pt}%
    }}
    \vspace{10pt}

    \colorbox{findingbg}{\parbox{0.94\linewidth}{%
      \vspace{10pt}\centering
      {\fontsize{60}{70}\selectfont\bfseries\color{secondary} 6.2$\boldsymbol{\times}$}\\[3pt]
      {\fontsize{30}{38}\selectfont\bfseries\color{textlight} Cell-Type-Specific Wiring}\\[5pt]
      {\fontsize{27}{35}\selectfont\color{textgray} Inhibitory interneurons show 6.2$\times$ higher connection\\specificity than excitatory neurons — challenging the\\assumption of broad inhibitory blanket coverage.}\vspace{10pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════
% ROW BAND C (row17 to bottom) — Implications | Future | Takeaways
% ═══════════════════════════════════════════════════════

% Col 1: Implications
\posterbox[bluecard, title={Implications}
]{name=implications, column=1, between=row17 and bottom}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item Modular motifs suggest the brain uses a finite vocabulary of circuit elements for cortical computation
    \item Hub neurons as disproportionate network drivers explain how focal lesions produce widespread effects
    \item Direct relevance to neurological disease mechanisms and brain-computer interface design
  \end{itemize}
}

% Col 2: Future Directions
\posterbox[tealcard, title={Future Directions}
]{name=future, column=2, between=row17 and bottom}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item Extend connectomic approach to additional brain regions and species
    \item Build a complete wiring diagram of the mammalian brain
    \item Integrate with functional recordings for structure-function mapping
    \item Refine automated reconstruction for higher throughput
  \end{itemize}
  \vspace{4pt}
  \colorbox{secondary!20!bgposter}{\parbox{0.90\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{28}{34}\selectfont\color{secondary!80!white} Open-access data \& tools released to\\accelerate community discovery}\vspace{6pt}%
  }}
}

% Col 3: Key Takeaways + Reference
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row17 and bottom}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Largest connectomic dataset to date:\\\textbf{$\sim$125K neurons}, \textbf{$\sim$54M synapses}
    \item \textbf{37 circuit motifs} reveal modular wiring principles underlying cortical computation
    \item Hub neurons (\textbf{3.5\%} pop.) drive \textbf{28\%} of output —\\(highly skewed influence distribution)
  \end{itemize}
  \vspace{6pt}
  \begin{center}
  \colorbox{primary!25!bgposter}{\parbox{0.90\linewidth}{%
    \centering\vspace{5pt}
    {\fontsize{26}{32}\selectfont\color{textgray}%
      \textit{Nature} (2024) $\bullet$ DOI: 10.1038/s41586-024-07487-w}\vspace{5pt}%
  }}
  \end{center}
}

\end{tcbposter}
\end{document}
